I wrote something like this. Please place it under js/plugins and then add using plugin manager to give it a try. Is this what you ware looking for?
Here is the code, you can remove checking for boat and ship if you want player to move like this also:
JavaScript:
var DJ = DJ || {};
DJ.SKID = DJ.SKID || {};

const _slowDownAt = 0.4;

DJ.SKID.Game_CharacterBase_distancePerFrame = Game_CharacterBase.prototype.distancePerFrame;
Game_CharacterBase.prototype.distancePerFrame = function() {
    if($gamePlayer.isInBoat() || $gamePlayer.isInShip()) {
        const xDist = Math.abs(this._x - this._realX);
        const yDist = Math.abs(this._y - this._realY);
        if(xDist > _slowDownAt || yDist > _slowDownAt) {
            this.setMoveSpeed(5);
        }
        else {
            this.setMoveSpeed(3);
        }
    }
    return DJ.SKID.Game_CharacterBase_distancePerFrame.call(this);
}

I can't test it right now, but you can try this: Instead of checking for boat which is irrelevant in your case I check whether the input is pressed and execute stop logic only when its not pressed.
JavaScript:
var DJ = DJ || {};
DJ.SKID = DJ.SKID || {};
const _slowDownAt = 0.4;
DJ.SKID.Game_CharacterBase_distancePerFrame = Game_CharacterBase.prototype.distancePerFrame;
Game_CharacterBase.prototype.distancePerFrame = function() {
    if(this.isMoving()) {
        const realXDist = $gameTemp.isDestinationValid() ? $gameTemp.destinationX() : this._realX;
        const realYDist = $gameTemp.isDestinationValid() ? $gameTemp.destinationY() : this._realY;
        const xDist = Math.abs(this._x - realXDist);
        const yDist = Math.abs(this._y - realYDist);
        if(xDist > _slowDownAt || yDist > _slowDownAt) {
            this.setSlowDown(false);
        }
        else if (Input.dir4 === 0) {
            this.setSlowDown(true)
        }
    }
    else this.setSlowDown(false);
    return DJ.SKID.Game_CharacterBase_distancePerFrame.call(this);
}
DJ.SKID.Game_CharacterBase_realMoveSpeed = Game_CharacterBase.prototype.realMoveSpeed;
Game_CharacterBase.prototype.realMoveSpeed = function() {
    if(!this.getSlowDown()) return DJ.SKID.Game_CharacterBase_realMoveSpeed.call(this);
    else return 2 + (this.isDashing() ? 1 : 0);
}
Game_CharacterBase.prototype.setSlowDown = function(slowDown) {
    this._slowDown = slowDown;
}
Game_CharacterBase.prototype.getSlowDown = function() {
    return this._slowDown || false;
}
EDIT: fixed bugs. Ongoing issue is that if player uses touch the movement will again be jerky.
EDIT2: This version seems to work with both touch and pressing keys. Please test it.
